// Normaliza los datos de candidato + ficha de contratación en un único objeto
// que usaremos para rellenar los 5 documentos.
// PENDIENTE: ajustar los paths reales una vez confirmado el endpoint de la ficha.

const candidato = $input.first().json; // respuesta de GET Candidato
const ficha = $node["GET Ficha de contratación (PENDIENTE endpoint real)"].json;

const nombre = `${candidato.data.attributes['first-name']} ${candidato.data.attributes['last-name']}`;

// TODO: mapear los nombres de campo reales del kit de entrevista una vez confirmados
const dni = ficha.dni; // placeholder
const puesto = ficha.puesto_trabajo; // placeholder
const fechaInicio = ficha.fecha_inicio; // formato TBD, viene como fecha de TT (ISO?)

const fecha = new Date(fechaInicio);
const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];

return [{
  json: {
    candidate_id: candidato.data.id,
    nombre,
    dni,
    puesto,
    empresa: 'ONESTAWAVE, S.L.',
    fecha_dia: String(fecha.getDate()),
    fecha_mes: meses[fecha.getMonth()],
    fecha_anio: String(fecha.getFullYear()),
    fecha: `${fecha.getDate()} de ${meses[fecha.getMonth()]} de ${fecha.getFullYear()}`,
    fecha_lugar: 'Sant Cugat del Vallès'
  }
}];
